<?php
namespace Tests\Feature;use App\Models\AudioVoiceProfile;use App\Models\NewsArticle;use App\Models\NewsNarration;use App\Services\NewsNarrationService;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Http;use Illuminate\Support\Facades\Storage;use Tests\TestCase;
class NewsNarrationTest extends TestCase{use RefreshDatabase;
 public function test_audio_requires_review_before_public_access():void{Storage::fake('public');config(['luzicity.ai.openai_api_key'=>'test']);Http::fake(['https://api.openai.com/v1/audio/speech'=>Http::response('fake-mp3',200)]);$user=\App\Models\User::factory()->create();$article=NewsArticle::create(['author_id'=>$user->id,'title'=>'Notícia narrada','slug'=>'noticia-narrada','body'=>'Conteúdo da notícia','status'=>'draft']);$voice=AudioVoiceProfile::create(['name'=>'Voz','provider'=>'openai','voice'=>'alloy','model'=>'gpt-4o-mini-tts','format'=>'mp3','cost_per_million_chars'=>15]);$n=NewsNarration::create(['news_article_id'=>$article->id,'audio_voice_profile_id'=>$voice->id,'status'=>'queued','input_text'=>'Texto para narrar','character_count'=>17,'estimated_cost'=>0.001]);app(NewsNarrationService::class)->generate($n);$this->assertSame('pending_review',$n->fresh()->status);$this->get(route('news.audio',$article))->assertNotFound();$n->update(['status'=>'approved']);$this->get(route('news.audio',$article))->assertRedirect();}
}
